async function fetchTechNews(category) {
  try {
    const res = await fetch(`/api/news?category=${category}`);
    if (!res.ok) throw new Error('Network error: ' + res.status);
    const data = await res.json();
    return data.data;
  } catch (err) {
    console.error('Fetch failed:', err.message);
    return [];
  }
}

